          fig: '<svg viewBox="0 0 320 100" role="img" aria-label="把前半句分成幾小段，起支放在這裡意思不合"><g font-size="17" fill="var(--ink)"><text x="8" y="50">這個月</text><text x="74" y="50">生活費</text><text x="140" y="50">快</text><text x="234" y="50">了</text></g><rect x="166" y="26" width="56" height="34" rx="6" fill="none" stroke="var(--pri)" stroke-width="2.5"/><text x="174" y="50" font-size="17" fill="var(--ink)">起支</text><text x="8" y="90" font-size="13" fill="var(--ink)">這裡的「起支」意思不合，先檢查它。</text></svg>',
